import { useIsMutating, useQueryClient } from '@tanstack/react-query';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
import { getMaxOrderQuantity } from 'app/utils/maxOrderQuantity';

/**
 * The minimal basket shape this hook needs, regardless of which caller supplies it: the
 * post-auth callback (`useWishlistAuthDrawer.ts`, wired in this step) passes the resolved value
 * of its own `mergeBasket` mutation directly; the cart drawer's render guard
 * (`overrides/app/pages/cart/cartDrawerContainer.tsx`, step 4.6 — not yet built) will pass its
 * own `useCurrentBasket()` data. `Pick`-narrowed, matching `cartItemMapper.ts`'s own established
 * pattern for taking an untyped-at-the-edges SDK response and narrowing it to only the fields a
 * pure function actually reads, rather than depending on the exact generic SDK response type
 * either caller's own mutation/query hook happens to produce.
 */
export type CartCapBasket = Pick<ShopperBasketsV2Types.Basket, 'basketId' | 'lastModified' | 'productItems'>;

/**
 * Outcome of one `capBasketQuantities` call. A discriminated union (typescript.md's guidance for
 * variant/state modelling) rather than a boolean-plus-optional-error: each branch is something a
 * caller could reasonably want to react to differently, and no AC or copy exists yet for any of
 * them (that is `useCartMessages`, step 4.3, not built) — this file only reports what happened,
 * it does not decide what the shopper sees.
 */
export type CartCapResult =
  | { status: 'not-needed' }
  | { status: 'skipped'; reason: 'mutation-in-flight' | 'already-attempted-this-version' }
  | { status: 'corrected' }
  | { status: 'error'; error: unknown };

/**
 * `getMaxOrderQuantity` is typed for a SCAPI product response (`id: string` required — see
 * `overrides/app/utils/maxOrderQuantity.ts`). A basket line item has no `id` field at all: only
 * `itemId`/`productId` (confirmed against the generated `BasketProductItem` type — verified via
 * a throwaway `tsc` repro that assigning a same-shaped object to a type requiring `id` fails
 * with "Property 'id' is missing"), so passing one directly does not type-check, despite it
 * carrying the same `{[key: string]: any}` catch-all a real `c_maxOrderQuantity` value would
 * arrive through once SFCC-268 ships. `product-item/index.tsx` already lives with the identical
 * gap at its own `getMaxOrderQuantity(product)` call site (`type SfccProduct = any`, lines 171
 * and 331) — narrowed here with an explicit, commented cast instead of a bare `any` parameter,
 * per typescript.md's "no `any` without an inline comment" rule.
 */
const getLineMaxOrderQuantity = (item: ShopperBasketsV2Types.BasketProductItem): number =>
  getMaxOrderQuantity(item as unknown as Parameters<typeof getMaxOrderQuantity>[0]);

/**
 * A line needs correction once its quantity exceeds the cap — i.e. once it reaches the smallest
 * over-cap value (`max + 1`; `4` when `max` is `3`) or anything above it. Written as `quantity >
 * max` rather than comparing against a separately-named `max + 1` boundary, but the two are the
 * same comparison: this must be a "the whole range above the boundary" check, not an
 * exact-equality check against a single value — an equality check against `max + 1` alone would
 * correctly catch a line at 4 but wrongly leave a line at 5 or more uncorrected, which is
 * observably wrong against this hook's own test fixture (a line at 5 must reduce to 3, not stay
 * at 5).
 */
const needsQuantityCorrection = (
  item: ShopperBasketsV2Types.BasketProductItem,
): item is ShopperBasketsV2Types.BasketProductItem & { quantity: number } =>
  typeof item.quantity === 'number' && item.quantity > getLineMaxOrderQuantity(item);

/**
 * SFCC baskets carry no explicit version counter. `basketId` + `lastModified` change together on
 * every write SFCC accepts (both real fields on the generated `Basket` type), so the pair is a
 * workable proxy for "the exact basket state a correction was last attempted against" — this is
 * this file's own reasoned choice, not sourced from an existing codebase precedent or doc.
 */
const getBasketVersionKey = (basket: CartCapBasket): string => `${basket.basketId ?? ''}:${basket.lastModified ?? ''}`;

/**
 * Storage key for "which basket version has a correction already been attempted against."
 * Deliberately not a `useRef` — the post-auth callback (`useWishlistAuthDrawer.ts`) and the
 * future render guard (step 4.6) each get their own separate `useCartMergeAndCap()` call, and
 * therefore their own separate refs, since they mount in two different React component trees. A
 * plain ref cannot coordinate between them. Piggybacking on the already-global `QueryClient` (the
 * same one `useIsMutating` below reads from) via `getQueryData`/`setQueryData` gives real
 * cross-instance-shared storage without inventing a new module-level singleton or Context
 * provider. It is also, unlike a React-render-time hook value, live/imperative — reading and then
 * immediately writing it inside `capBasketQuantities` with no `await` in between (see that
 * function) leaves no window for two near-simultaneous calls to both pass the check before either
 * has recorded its attempt, since JavaScript runs that synchronous read-then-write as one
 * uninterruptible step.
 */
const CAP_ATTEMPT_QUERY_KEY = ['zimmCartMergeAndCap', 'attemptedBasketVersion'] as const;

export type UseCartMergeAndCapReturn = {
  /**
   * Checks every basket line against `getMaxOrderQuantity` and, if any line exceeds its cap,
   * issues one `updateItemsInBasket` write reducing every over-cap line to its own max in a
   * single request (matching the SFCC-11 plan's "one write" framing even when more than one line
   * needs correcting). Resolves only once that write — if one was issued — has fully settled, so
   * a caller sequencing merge -> cap -> a future wishlist-resume can `await` this in turn without
   * racing it.
   */
  capBasketQuantities: (basket: CartCapBasket) => Promise<CartCapResult>;
};

/**
 * Hook — the shared "cap" half of SFCC-250's merge-then-cap flow. Two callers share this one
 * implementation, not two copies: the post-auth callback inside `useWishlistAuthDrawer.ts`'s own
 * `isRegistered` effect (wired in this step, right after that effect's existing `mergeBasket`
 * call), and the cart drawer's render guard, which will live in
 * `overrides/app/pages/cart/cartDrawerContainer.tsx` (not yet built — a later step, 4.6, wires
 * that second call site; this hook is written to support it, not to assume it already exists).
 *
 * Per rules-of-hooks, call this at the top level of whichever hook or component needs it — never
 * from inside a `useEffect` callback — and invoke the returned `capBasketQuantities` function
 * itself from inside the effect/render path instead.
 *
 * @returns `capBasketQuantities`, the one function both callers invoke.
 */
export const useCartMergeAndCap = (): UseCartMergeAndCapReturn => {
  // Render-time snapshot of React Query's GLOBAL mutation count — every mutation anywhere in the
  // app, not just this hook's own. commerce-sdk-react's basket mutation hooks set no
  // `mutationKey` at all (confirmed directly against `useShopperBasketsMutation`'s own
  // implementation, `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperBasketsV2/
  // mutation.js` and the shared `hooks/useMutation.js` it calls into), so an unscoped
  // `useIsMutating()` is the only reading that can see any of them at all — this is also exactly
  // what gives two separate hook-call instances (this callback and the future render guard)
  // genuine cross-component visibility into each other's writes without this file inventing its
  // own shared "is anything mutating" flag.
  const isMutating = useIsMutating();
  const queryClient = useQueryClient();
  const updateItemsInBasket = useShopperBasketsMutation('updateItemsInBasket');

  const capBasketQuantities = async (basket: CartCapBasket): Promise<CartCapResult> => {
    // No-op while any mutation is in flight (this hook's own prior correction, the merge that
    // just ran, a shopper's manual quantity edit — anything) so this can never race a write
    // already under way. See this function's own JSDoc and the `isMutating` comment above.
    if (isMutating > 0) {
      return { status: 'skipped', reason: 'mutation-in-flight' };
    }

    const correctedItems = (basket.productItems ?? []).filter(needsQuantityCorrection).map((item) => ({
      itemId: item.itemId,
      productId: item.productId,
      quantity: getLineMaxOrderQuantity(item),
    }));

    if (correctedItems.length === 0) {
      return { status: 'not-needed' };
    }

    if (!basket.basketId) {
      // No basketId means there is nothing valid to address a write at — surface this as an
      // error rather than silently doing nothing, so a caller can tell "nothing needed fixing"
      // apart from "something needed fixing and couldn't be".
      return { status: 'error', error: new Error('useCartMergeAndCap: basket is missing a basketId.') };
    }

    const versionKey = getBasketVersionKey(basket);
    if (queryClient.getQueryData<string>(CAP_ATTEMPT_QUERY_KEY) === versionKey) {
      // Loop guard: a correction has already been attempted against this exact basket state,
      // whether it succeeded or failed — do not retry it. See CAP_ATTEMPT_QUERY_KEY's own
      // comment for why this is a live cache read rather than a per-instance ref, and why
      // setting it below, before the `await`, is what keeps this race-free.
      return { status: 'skipped', reason: 'already-attempted-this-version' };
    }
    queryClient.setQueryData(CAP_ATTEMPT_QUERY_KEY, versionKey);

    try {
      await updateItemsInBasket.mutateAsync({
        parameters: { basketId: basket.basketId },
        body: correctedItems,
      });
      return { status: 'corrected' };
    } catch (error) {
      // Surfaced to the caller, not retried: the version is already marked attempted above, so a
      // later call against this same unchanged basket state returns 'skipped' rather than
      // hammering the server again — no retry storm.
      return { status: 'error', error };
    }
  };

  return { capBasketQuantities };
};

