8	import { useDisclosure } from '@chakra-ui/react';
9	import {
10	  AuthHelpers,
11	  useAuthHelper,
12	  useCustomerType,
13	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
14	} from '@salesforce/commerce-sdk-react';
15	import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
16	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
17	import {
18	  getAuthorizePasswordlessErrorMessage,
19	  getLoginPasswordlessErrorMessage,
20	  getPasswordlessCallbackUrl,
21	} from '@salesforce/retail-react-app/app/utils/auth-utils';
22	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
23	import {
24	  setSessionJSONItem,
25	  getSessionJSONItem,
26	  clearSessionJSONItem,
27	  buildRedirectURI,
28	} from '@salesforce/retail-react-app/app/utils/utils';
29	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
30	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
31	
32	// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
33	// panel is visible and Chakra's FocusLock has initialised.
34	const DRAWER_ANIMATION_DELAY_MS = 150;
35	
36	// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist an
37	// intent before the redirect so the pending wishlist action can be replayed on return.
38	// Keyed by `intentId` (see UseWishlistAuthDrawerParams) rather than a bare flag: the header
39	// and a PDP can both mount their own `useWishlistAuthDrawer` instance on the same returned
40	// page, each with a different `onAuthSuccess` — a bare boolean let whichever instance's
41	// effect ran first steal the intent and fire its own callback instead of the one that
42	// actually initiated the redirect (SFCC-742 review finding).
43	const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';
44	
45	type PendingWishlistIntent = { intentId: string; timestamp: number };
46	
47	// A cancelled/abandoned IDP round-trip has no reliable "the user said no" signal we can
48	// observe here — the callback route that owns the actual redirect-back is base SFCC code,
49	// not this hook. Bound the blast radius by age instead: long enough for a slow IDP
50	// round-trip, short enough that an abandoned attempt can't misfire a much later, unrelated
51	// registration in the same tab.
52	const PENDING_WISHLIST_INTENT_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes
53	
54	// Reads the pending intent, transparently discarding (and clearing) one that's aged out.
55	const readPendingWishlistIntent = (): PendingWishlistIntent | undefined => {
56	  const stored = getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY) as PendingWishlistIntent | undefined;
57	  if (!stored) return undefined;
58	  if (Date.now() - stored.timestamp > PENDING_WISHLIST_INTENT_MAX_AGE_MS) {
59	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
60	    return undefined;
61	  }
62	  return stored;
63	};
64	
65	const messages = defineMessages({
66	  drawerTitle: {
67	    id: 'wishlist.auth.drawer.title',
68	    defaultMessage: 'Wishlist',
69	  },
70	});
71	
72	const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';
73	
74	type UseWishlistAuthDrawerParams = {
75	  onAuthSuccess?: () => void;
76	  /** Identifies which mounted instance initiated a social-IDP redirect, so that after the
77	   *  round-trip only the matching instance's `onAuthSuccess` fires — see
78	   *  `PENDING_WISHLIST_INTENT_KEY`'s comment. Must be stable and distinct per call site
79	   *  (e.g. `'header-wishlist'`, `'pdp-wishlist'`), not per render. */
80	  intentId: string;
81	};
82	
83	export type UseWishlistAuthDrawerReturn = {
84	  isOpen: boolean;
85	  handleDrawerClose: () => void;
86	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
87	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
88	  triggerRef: RefObject<HTMLElement>;
89	  drawerTitle: string;
90	  description: string;
91	  emailValue: string;
92	  onEmailChange: (val: string) => void;
93	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
94	  onSignInWithApple?: () => void;
95	  onSignInWithGoogle?: () => void;
96	  isSocialEnabled: boolean;
97	  /** Whether the passwordless email login flow is available per site config. */
98	  isPasswordlessEnabled: boolean;
99	  emailInputRef: RefObject<HTMLInputElement>;
100	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
101	  socialError?: string;
102	  onCreateAccount: () => void;
103	  isOtpAuthOpen: boolean;
104	  onOtpAuthClose: () => void;
105	  form: UseFormReturn<FieldValues>;
106	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
107	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
108	  registerModal: ReturnType<typeof useAuthModal>;
109	};
110	
111	/**
112	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
113	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
114	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
115	 *
116	 * @returns All state and event handlers needed to render and drive the auth gate UI.
117	 */
118	export const useWishlistAuthDrawer = ({
119	  onAuthSuccess,
120	  intentId,
121	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
122	  const { formatMessage } = useIntl();
123	  const { t } = useUiCopy();
124	  const { data: customer } = useCurrentCustomer();
125	  const { isRegistered } = useCustomerType();
126	  const { isOpen, onOpen, onClose } = useDisclosure();
127	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
128	  const [emailValue, setEmailValue] = useState('');
129	  const [socialError, setSocialError] = useState<string | undefined>();
130	  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
131	  const form = useForm();
132	  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
133	  const emailInputRef = useRef<HTMLInputElement>(null);
134	
135	  // AC10 focus-return: capture the clicked/focused trigger element at click time.
136	  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
137	  // guaranteed for all consumers. document.activeElement at onClick time is always the
138	  // element that was interacted with, regardless of how the child is implemented.
139	  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
140	  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);
141	
142	  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
143	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
144	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
145	  const mergeBasket = useShopperBasketsMutation('mergeBasket');
146	  // SFCC-250 step 4.2: the shared cap function, called below once the merge above resolves.
147	  // Must be called here, at this hook's own top level — not from inside the effect below — per
148	  // rules of hooks; see `useCartMergeAndCap`'s own doc comment.
149	  const { capBasketQuantities } = useCartMergeAndCap();
150	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
151	  const registerModal = useAuthModal(REGISTER_VIEW);
152	  const { locale } = useMultiSite();
153	
154	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
155	  const loginConfig = (getConfig().app.login || {}) as any;
156	  const passwordlessConfig = loginConfig.passwordless;
157	  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
158	  const isSocialEnabled = !!loginConfig.social?.enabled;
159	  const idps: string[] = loginConfig.social?.idps ?? [];
160	  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
161	  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;
162	
163	  // Move focus to the email input once the drawer's enter animation completes.
164	  useEffect(() => {
165	    if (!isOpen) return;
166	    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
167	    return () => clearTimeout(timer);
168	  }, [isOpen]);
169	
170	  // When the customer transitions to registered while the drawer (or OTP modal) is open,
171	  // close everything, fire the deferred action, and merge the guest basket the shopper was
172	  // just signed out of (passwordless login only — see the merge call's own comment below).
173	  useEffect(() => {
174	    if (isRegistered && (isOpen || isOtpAuthOpen)) {
175	      onClose();
176	      setIsOtpAuthOpen(false);
177	      onAuthSuccess?.();
178	
179	      // Passwordless sign-in switches the SDK session to the registered customer without
180	      // merging the guest basket — left unmerged, the shopper's guest-basket items are
181	      // orphaned, not just miscounted. This mirrors base `use-auth-modal.js`'s own
182	      // `handleMergeBasket`, called from that file's structural equivalent of this effect
183	      // (its own `useEffect(..., [isRegistered])`) rather than from `handleOtpVerification` —
184	      // `isRegistered` (from `useCustomerType()`) is the signal that customer-dependent state
185	      // has actually caught up with the session switch, not just that the login mutation
186	      // resolved, which is presumably why base waits for it here too. The social-IDP route
187	      // needs no merge added here — it redirects through base `social-login-redirect`, which
188	      // already merges on its own. Create-account never reaches this branch — a new customer
189	      // has no prior basket to merge, and `handleTriggerClick` only opens this drawer for a
190	      // guest in the first place, so every path reaching this effect already started as a
191	      // guest session (unlike base, no `prevAuthType === 'guest'` check is needed to establish
192	      // that).
193	      //
194	      // Deliberately does not gate on `hasBasketItem` the way base does: that would add a new
195	      // basket-loading dependency to a hook that has never needed one, and the failure mode of
196	      // getting its timing wrong (a merge silently skipped when it shouldn't be) is worse than
197	      // the cost of one occasional harmless merge call against an empty basket.
198	      //
199	      // productItemMergeMode is 'sum_quantities', not the SDK's 'higher_quantity' default —
200	      // deliberate, not a copy of base's call. This changes the result of every merge, not
201	      // just over-the-cap ones: a guest who adds one unit of an item, then signs into an
202	      // account that already had one unit of that same item, gets two units after merge, not
203	      // one. No AC describes this, so a future reader/tester with no memory of this decision
204	      // needs it stated plainly: two units is intended.
205	      mergeBasket.mutate(
206	        {
207	          headers: {
208	            // Not required since the request has no body, but CommerceAPI throws a
209	            // '419 - Unsupported Media Type' error if this header is removed.
210	            'Content-Type': 'application/json',
211	          },
212	          parameters: {
213	            createDestinationBasket: true,
214	            productItemMergeMode: 'sum_quantities',
215	          },
216	        },
217	        {
218	          // SFCC-250 step 4.2: cap every line at its real max-order-quantity right after a merge
219	          // that may have just combined two same-SKU lines into one now-over-cap line — merge
220	          // must resolve before cap runs, which is exactly what chaining off `onSuccess` (rather
221	          // than a separate, uncoordinated effect) guarantees. A later step (4.4, not yet built)
222	          // will resume any pending wishlist-move action after this settles; `capBasketQuantities`
223	          // already resolves only once its own write (if any) has fully settled, so that future
224	          // addition can sequence after it here without racing it.
225	          //
226	          // Uses `mutate`'s own `onSuccess` rather than switching this call to `mutateAsync` +
227	          // `await`: `mutate` never rejects to its caller (React Query swallows the error into
228	          // the mutation's own state), which is the exact behaviour this merge call already had
229	          // before this step — preserved deliberately, since no AC describes shopper-facing
230	          // feedback for a failed post-login basket merge and inventing copy for it is out of
231	          // this step's scope (interim messaging is `useCartMessages`, step 4.3, not built yet).
232	          // `mutateAsync` + `await` with no `catch` would instead turn that same failure into an
233	          // unhandled promise rejection, which this design avoids entirely rather than papering
234	          // over with an empty `catch`.
235	          onSuccess: (mergedBasket) => {
236	            void capBasketQuantities(mergedBasket);
237	          },
238	        },
239	      );
240	    }
241	  }, [isRegistered]);
242	
243	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
244	  // On mount, if the shopper is already registered and a pending intent was stored before the
245	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
246	  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
247	  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
248	  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
249	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
250	  // intentId are intentionally omitted because the intent fires at most once per redirect
251	  // cycle, and the flag is cleared before any re-render that could change either.
252	  useEffect(() => {
253	    if (!isRegistered) return;
254	    const pending = readPendingWishlistIntent();
255	    if (!pending || pending.intentId !== intentId) return;
256	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
257	    onAuthSuccess?.();
258	    // eslint-disable-next-line react-hooks/exhaustive-deps
259	  }, [isRegistered]);
260	
261	  const handleDrawerClose = () => {
262	    onClose();
263	    form.reset();
264	    setEmailValue('');
265	  };
266	
267	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
268	    // e.currentTarget is always the element the handler is attached to — reliable across
269	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
270	    triggerRef.current = e.currentTarget;
271	    if (customer?.isRegistered) {
272	      onAuthSuccess?.();
273	    } else {
274	      onOpen();
275	    }
276	  };
277	
278	  const handlePasswordlessLogin = async (email: string) => {
279	    try {
280	      const redirectPath = window.location.pathname + (window.location.search ?? '');
281	      await authorizePasswordlessLogin.mutateAsync({
282	        userid: email,
283	        mode: passwordlessConfig?.mode,
284	        locale: locale.id,
285	        ...(callbackURL && {
286	          callbackURI: (() => {
287	            const url = new URL(callbackURL);
288	            url.searchParams.set('redirectUrl', redirectPath);
289	            return url.toString();
290	          })(),
291	        }),
292	      });
293	      return { success: true };
294	    } catch (error) {
295	      return {
296	        success: false,
297	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
298	      };
299	    }
300	  };
301	
302	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
303	    try {
304	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
305	      return { success: true };
306	    } catch (e) {
307	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
