import { describe, test, expect, vi, beforeEach } from 'vitest';
import { act } from '@testing-library/react';
import type { ShopperBasketsV2Types } from 'commerce-sdk-isomorphic';
import { renderHookWithQueryClient } from 'app/test-utils/renderWithProviders';
import { useCartMergeAndCap, type CartCapBasket, type CartCapResult } from './useCartMergeAndCap';

// TEMPORARY adversarial probe file — delete after use. Mirrors the exact mocking pattern from
// useCartMergeAndCap.test.ts (mock useShopperBasketsV2Mutation + useIsMutating only, keep the
// real QueryClient via importOriginal).
const { mockMutateAsync, mockUseIsMutating } = vi.hoisted(() => ({
  mockMutateAsync: vi.fn(),
  mockUseIsMutating: vi.fn(() => 0),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperBasketsV2Mutation: () => ({ mutateAsync: mockMutateAsync }),
}));

vi.mock('@tanstack/react-query', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@tanstack/react-query')>();
  return { ...actual, useIsMutating: mockUseIsMutating };
});

const makeLineItem = (
  overrides: Partial<ShopperBasketsV2Types.BasketProductItem> = {},
): ShopperBasketsV2Types.BasketProductItem => ({
  itemId: 'item-1',
  productId: 'product-1',
  quantity: 1,
  ...overrides,
});

const makeBasket = (
  productItems: ShopperBasketsV2Types.BasketProductItem[],
  overrides: Partial<CartCapBasket> = {},
): CartCapBasket => ({
  basketId: 'basket-1',
  lastModified: '2026-09-20T00:00:00.000Z',
  productItems,
  ...overrides,
});

const flushMicrotasks = () => new Promise((resolve) => setTimeout(resolve, 0));

describe('useCartMergeAndCap — adversarial probes (temporary, delete after run)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseIsMutating.mockReturnValue(0);
    mockMutateAsync.mockResolvedValue({});
  });

  test('probe 1: two truly concurrent calls against the same basket version issue exactly one write', async () => {
    let resolveWrite: (value: unknown) => void = () => {};
    mockMutateAsync.mockImplementation(
      () =>
        new Promise((resolve) => {
          resolveWrite = resolve;
        }),
    );

    const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
    const basket = makeBasket([makeLineItem({ quantity: 10 })]);

    let r1!: CartCapResult;
    let r2!: CartCapResult;

    await act(async () => {
      const p1 = result.current.capBasketQuantities(basket);
      const p2 = result.current.capBasketQuantities(basket);
      // Both calls' synchronous prefixes (including the loop guard's setQueryData) have
      // already run to completion by this point — neither call yielded control until its own
      // first `await` — so mutateAsync must already be pinned at exactly one call here, BEFORE
      // the write is even resolved.
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
      resolveWrite({});
      [r1, r2] = await Promise.all([p1, p2]);
    });

    expect(mockMutateAsync).toHaveBeenCalledTimes(1);
    const statuses = [r1.status, r2.status].sort();
    expect(statuses).toEqual(['corrected', 'skipped']);
    const skipped = [r1, r2].find((r) => r.status === 'skipped');
    expect(skipped).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
  });

  test('probe 2: after a rejection, 5 further calls against the same unchanged basket never re-issue the write', async () => {
    mockMutateAsync.mockRejectedValueOnce(new Error('server rejected the quantity update'));
    const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
    const basket = makeBasket([makeLineItem({ quantity: 10 })]);

    const first = await act(async () => result.current.capBasketQuantities(basket));
    expect(first.status).toBe('error');
    expect(mockMutateAsync).toHaveBeenCalledTimes(1);

    for (let i = 0; i < 5; i += 1) {
      // eslint-disable-next-line no-await-in-loop
      const outcome = await act(async () => result.current.capBasketQuantities(basket));
      expect(outcome).toEqual({ status: 'skipped', reason: 'already-attempted-this-version' });
      expect(mockMutateAsync).toHaveBeenCalledTimes(1);
    }
  });

  describe('probe 3: quantity > max boundary holds at max values other than the fallback of 3', () => {
    test('max=2, qty=2: not-needed, no write', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 2, c_maxOrderQuantity: 2 } as never)]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'not-needed' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });

    test('max=2, qty=3: corrected to 2', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([
        makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 3, c_maxOrderQuantity: 2 } as never),
      ]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'a', productId: 'p-a', quantity: 2 }],
      });
    });

    test('max=5, qty=5: not-needed, no write', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 5, c_maxOrderQuantity: 5 } as never)]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'not-needed' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });

    test('max=5, qty=6: corrected to 5', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([
        makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 6, c_maxOrderQuantity: 5 } as never),
      ]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'a', productId: 'p-a', quantity: 5 }],
      });
    });

    test('max=1, qty=1: not-needed, no write', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([makeLineItem({ quantity: 1, c_maxOrderQuantity: 1 } as never)]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'not-needed' });
      expect(mockMutateAsync).not.toHaveBeenCalled();
    });

    test('max=1, qty=2: corrected to 1', async () => {
      const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
      const basket = makeBasket([
        makeLineItem({ itemId: 'a', productId: 'p-a', quantity: 2, c_maxOrderQuantity: 1 } as never),
      ]);

      const outcome = await act(async () => result.current.capBasketQuantities(basket));

      expect(outcome).toEqual({ status: 'corrected' });
      expect(mockMutateAsync).toHaveBeenCalledWith({
        parameters: { basketId: 'basket-1' },
        body: [{ itemId: 'a', productId: 'p-a', quantity: 1 }],
      });
    });
  });

  test('probe 5: awaiting capBasketQuantities genuinely waits for the internal write to settle', async () => {
    let resolveWrite: (value: unknown) => void = () => {};
    mockMutateAsync.mockImplementation(
      () =>
        new Promise((resolve) => {
          resolveWrite = resolve;
        }),
    );

    const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
    const basket = makeBasket([makeLineItem({ quantity: 10 })]);

    const order: string[] = [];
    const run = (async () => {
      order.push('call:start');
      await result.current.capBasketQuantities(basket);
      order.push('call:after-await');
    })();

    await act(async () => {
      await flushMicrotasks();
    });
    order.push('checkpoint:before-resolve');
    expect(mockMutateAsync).toHaveBeenCalledTimes(1);
    // 'call:after-await' must NOT be in here yet — the write is still deliberately unresolved.
    expect(order).toEqual(['call:start', 'checkpoint:before-resolve']);

    resolveWrite({});
    await act(async () => {
      await run;
    });
    order.push('checkpoint:final');

    expect(order).toEqual(['call:start', 'checkpoint:before-resolve', 'call:after-await', 'checkpoint:final']);
  });

  test('probe 6: a non-zero useIsMutating count blocks the write even for a totally unrelated mutation', async () => {
    mockUseIsMutating.mockReturnValue(3);
    const { result } = renderHookWithQueryClient(() => useCartMergeAndCap());
    const basket = makeBasket([makeLineItem({ quantity: 10 })]);

    const outcome = await act(async () => result.current.capBasketQuantities(basket));

    expect(outcome).toEqual({ status: 'skipped', reason: 'mutation-in-flight' });
    expect(mockMutateAsync).not.toHaveBeenCalled();
  });
});

